				monitor.clearCancelled();
				monitor.setMessage("");
				monitor.setProgress(0);
				ConditionTestState conditionTestState = map.get(test);
				if (conditionTestState.isEnabled()) {
					startingTest(test);
					ConditionResult result;
					try {
						result = test.run(monitor);
